int n , m ; 
string s,t ; 
int hashA [maxn] ;
int POW [maxn] ; 
int get_hash ( int l , int r ) 
{
    return ( hashA[r] - hashA[l-1]*POW[r-l+1] + 1ll*mod*mod ) % mod ; 
}
signed main () 
{
    ios_base::sync_with_stdio(0); 
    cin.tie(0);cout.tie(0); 
    cin >> s >> t ; 
    n = s.size () , m = t.size () ; 
    s = ' ' + s , t = ' ' + t ; 
    POW [0] = 1 ; 
    for ( int i = 1 ; i <= n ; i ++ ) POW [i] = POW [i-1]*53%mod ; 
    for ( int i = 1 ; i <= n ; i ++ ) hashA [i] = (hashA[i-1]*53+s[i])%mod ; 
    int hashB = 0 ; 
    for ( int i = 1 ; i <= m ; i ++ ) hashB = (hashB*53+t[i])%mod ; 
    int res = 0 ; 
    for ( int i = 1 ; i <= n - m + 1 ; i ++ ) res += get_hash(i,i+m-1) == hashB ; 
    cout << res ; 
    return 0;
}
